#include <stdio.h>
int main(void) {
    int x = 42;
    int *p = &x;
    printf("%d\n", *p);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {10, 20, 30};
    int *p = arr;
    printf("%d\n", *(p + 2));
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 5;
    int *p = &x;
    int **pp = &p;
    printf("%d\n", **pp);
    return 0;
}

#include <stdio.h>
static int add(int a, int b) { return a + b; }
int main(void) {
    int (*fp)(int, int) = add;
    printf("%d\n", fp(2, 3));
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 3, b = 7;
    int *pa = &a, *pb = &b;
    int t = *pa;
    *pa = *pb;
    *pb = t;
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    int *p = arr;
    int sum = 0;
    for (int i = 0; i < 5; i++) sum += *(p + i);
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {5, 4, 3, 2, 1};
    int *p = arr;
    int *end = arr + 5;
    int sum = 0;
    while (p < end) {
        sum += *p;
        p++;
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {10, 20, 30, 40, 50};
    int *p = arr;
    int *q = arr + 4;
    int t = *p;
    *p = *q;
    *q = t;
    printf("%d %d\n", arr[0], arr[4]);
    return 0;
}

#include <stdio.h>
static int mul(int a, int b) { return a * b; }
static int sub(int a, int b) { return a - b; }
int main(void) {
    int (*ops[2])(int, int) = {mul, sub};
    printf("%d\n", ops[1](10, 4));
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 100;
    int *p = &x;
    int **pp = &p;
    **pp = 50;
    printf("%d\n", x);
    return 0;
}
